update public.pooja_steps set
  instruction_en = 'Fold the index and middle fingers. Close the right nostril with the thumb and the left with the ring and little fingers. Breathe IN through the left through the seven worlds, HOLD through the Gayatri, and breathe OUT through the right through om aapo jyoti.',
  instruction_ta = 'ஆட்காட்டி, நடுவிரல்களை மடக்கவும். வலது நாசியைக் கட்டைவிரலாலும், இடது நாசியை மோதிர, சுண்டு விரல்களாலும் அடைக்கவும். இடது நாசி வழியே ஏழு லோகங்களுடன் மூச்சை இழுக்கவும்; காயத்ரியுடன் நிறுத்தவும்; வலது நாசி வழியே "ஓம் ஆபோ ஜ்யோதி" உடன் வெளியிடவும்.',
  updated_at = now()
 where pooja_id = 'sandhyavandanam' and step_title_en = 'Pranayamam (japa)';

