 where pooja_id = 'sandhyavandanam' and step_title_en = 'Japasthanam Prokshanam';

-- --- assert ------------------------------------------------------------------
do $$
declare n int; t text;
begin
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam';
  if n <> 53 then raise exception 'rite has % steps, expected 53', n; end if;

  -- Nothing was left parked. A step still above 1000 is one ORDER does not
  -- name, which means it would sort to the end of the rite rather than vanish
  -- -- the kind of fault that shows up as a stray step at the bottom and not
  -- as an error.
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and step_number > 1000;
  if n > 0 then raise exception '% step(s) were never renumbered', n; end if;

  -- Dense 1..n, so the step sheet has no gaps and no two steps collide.
  select count(*) into n from (
    select step_number from public.pooja_steps where pooja_id = 'sandhyavandanam'
     group by step_number having count(*) > 1) d;
  if n > 0 then raise exception '% duplicated step_number(s)', n; end if;
  select count(*) into n from generate_series(1, 53) g
   where not exists (select 1 from public.pooja_steps where pooja_id = 'sandhyavandanam' and step_number = g);
  if n > 0 then raise exception '% gap(s) in step_number', n; end if;

  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and 'pratah' = any(modes);
  if n <> 39 then raise exception 'morning has % steps, expected 39', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and 'madhyahnika' = any(modes);
  if n <> 39 then raise exception 'noon has % steps, expected 39', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and 'sayam' = any(modes);
  if n <> 39 then raise exception 'evening has % steps, expected 39', n; end if;

  -- THE ACTUAL POINT OF THE MIGRATION, and neither half of it is a count.
  --
  -- No surviving instruction may name two different sittings. Checked against
  -- the stored rows rather than the generator: the generator validates its own
  -- strings, which proves nothing about what a renumber or a clone put in the
  -- table.
  select string_agg(step_title_en, likeN) into t from (
    select step_title_en, chr(10) || '    ' as likeN from public.pooja_steps
     where pooja_id = 'sandhyavandanam'
       and (case when instruction_en ~* '\mmorning\M' then 1 else 0 end
          + case when instruction_en ~* '\m(noon|midday)\M' then 1 else 0 end
          + case when instruction_en ~* '\mevening\M' then 1 else 0 end) > 1) x;
  if t is not null then raise exception 'step(s) still recite more than one sitting: %', t; end if;

  -- And none may hand the reader a homework assignment.
  select string_agg(step_title_en, ', ') into t from public.pooja_steps
   where pooja_id = 'sandhyavandanam' and instruction_en ~* 'do achamanam|do anga vandanam';
  if t is not null then raise exception 'step(s) still refer the reader elsewhere: %', t; end if;

  -- Each repeated step carries the SAME mantra as the step it repeats. The
  -- clone is an INSERT...SELECT so this holds by construction -- which is
  -- exactly why it is worth asserting: if someone later edits one of the two by
  -- hand, the construction no longer holds and nothing else would notice.
  select count(*) into n from public.pooja_steps a, public.pooja_steps b
   where a.pooja_id = 'sandhyavandanam' and a.step_title_en = 'Achamanam (after tarpanam)'
     and b.pooja_id = 'sandhyavandanam' and b.step_title_en = 'Achamanam'
     and a.mantra_sanskrit is not distinct from b.mantra_sanskrit
     and a.mantra_tamil is not distinct from b.mantra_tamil
     and a.mantra_translit is not distinct from b.mantra_translit;
  if n <> 1 then raise exception 'Achamanam (after tarpanam) does not carry Achamanam''s mantra'; end if;
  select count(*) into n from public.pooja_steps a, public.pooja_steps b
   where a.pooja_id = 'sandhyavandanam' and a.step_title_en = 'Anga Vandanam (after tarpanam)'
     and b.pooja_id = 'sandhyavandanam' and b.step_title_en = 'Anga Vandanam'
     and a.mantra_sanskrit is not distinct from b.mantra_sanskrit
     and a.mantra_tamil is not distinct from b.mantra_tamil
     and a.mantra_translit is not distinct from b.mantra_translit;
  if n <> 1 then raise exception 'Anga Vandanam (after tarpanam) does not carry Anga Vandanam''s mantra'; end if;
  select count(*) into n from public.pooja_steps a, public.pooja_steps b
   where a.pooja_id = 'sandhyavandanam' and a.step_title_en = 'Achamanam (before prokshanam)'
     and b.pooja_id = 'sandhyavandanam' and b.step_title_en = 'Achamanam'
     and a.mantra_sanskrit is not distinct from b.mantra_sanskrit
     and a.mantra_tamil is not distinct from b.mantra_tamil
     and a.mantra_translit is not distinct from b.mantra_translit;
  if n <> 1 then raise exception 'Achamanam (before prokshanam) does not carry Achamanam''s mantra'; end if;
  select count(*) into n from public.pooja_steps a, public.pooja_steps b
   where a.pooja_id = 'sandhyavandanam' and a.step_title_en = 'Anga Vandanam (before prokshanam)'
     and b.pooja_id = 'sandhyavandanam' and b.step_title_en = 'Anga Vandanam'
     and a.mantra_sanskrit is not distinct from b.mantra_sanskrit
     and a.mantra_tamil is not distinct from b.mantra_tamil
     and a.mantra_translit is not distinct from b.mantra_translit;
  if n <> 1 then raise exception 'Anga Vandanam (before prokshanam) does not carry Anga Vandanam''s mantra'; end if;

  -- Every step has Tamil, which is the 0048 lesson: that migration shipped
  -- eighteen steps with instruction_ta empty while every other pooja had Tamil
  -- on every row, and the step count did not notice.
  select string_agg(step_title_en, ', ') into t from public.pooja_steps
   where pooja_id = 'sandhyavandanam'
     and (coalesce(trim(step_title_ta), '') = '' or coalesce(trim(instruction_ta), '') = '');
  if t is not null then raise exception 'step(s) have no Tamil: %', t; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
